export class InteractiveMode {
	private runtimeHost: AgentSessionRuntime;
	private ui: TUI;
	private loadedResourcesContainer: Container;
	private chatContainer: Container;
	private pendingMessagesContainer: Container;
	private statusContainer: Container;
	private defaultEditor: CustomEditor;
	private editor: EditorComponent;
	private editorComponentFactory: EditorFactory | undefined;
	private autocompleteProvider: AutocompleteProvider | undefined;
	private autocompleteProviderWrappers: AutocompleteProviderFactory[] = [];
	private fdPath: string | undefined;
	private editorContainer: Container;
	private footer: FooterComponent;
	private footerDataProvider: FooterDataProvider;
	// Stored so the same manager can be injected into custom editors, selectors, and extension UI.
	private keybindings: KeybindingsManager;
	private version: string;
	private isInitialized = false;
	private stopCatalogRefresh: (() => void) | undefined;
	private onInputCallback?: (input: QueuedUserInput) => void;
	private pendingUserInputs: QueuedUserInput[] = [];
	private stagedSubmitImages: ImageContent[] | undefined;
	private fallbackImageAttachments = new Map<number, EditorImageAttachment>();
	private activeStatusIndicator: StatusIndicator | undefined = undefined;
	private readonly idleStatus = new IdleStatus();
	private workingMessage: string | undefined = undefined;
	private workingVisible = true;
	private workingIndicatorOptions: WorkingIndicatorOptions | undefined = undefined;
	private readonly defaultWorkingMessage = "Working...";
	private readonly defaultHiddenThinkingLabel = "Thinking...";
	private hiddenThinkingLabel = this.defaultHiddenThinkingLabel;

	private lastSigintTime = 0;
	private lastEscapeTime = 0;
	private readonly subagentEscape = new SubagentEscapeSequence();
	private anthropicSubscriptionWarningShown = false;

	// Status line tracking (for mutating immediately-sequential status updates)
	private lastStatusSpacer: Spacer | undefined = undefined;
	private lastStatusText: Text | undefined = undefined;

	// Streaming message tracking
	private streamingComponent: AssistantMessageComponent | undefined = undefined;
	private streamingMessage: AssistantMessage | undefined = undefined;

	// Smooth streaming state (smoothStreaming setting): the streaming component
	// reveals the target message grapheme by grapheme on a timer instead of
	// flashing whole chunks.
	private streamingTargetMessage: AssistantMessage | undefined = undefined;
	private streamingDisplayedLength = 0;
	private smoothStreamingTimer: NodeJS.Timeout | undefined = undefined;

	// Tool execution tracking: toolCallId -> component
	private pendingTools = new Map<string, ToolExecutionComponent>();

	// Tool output expansion state
	private toolOutputExpanded = false;

	// Thinking block visibility state
	private hideThinkingBlock = false;
	// lunr: collapsible reasoning — collapse completed thinking runs to a summary.
	private thinkingCollapse = true;
	// lunr: live timings for the streaming message's thinking runs; kept per
	// message so rebuildChatFromMessages can re-attach them.
	private thinkingRunTimings: ThinkingRunTiming[] = [];
	private thinkingTimingsByMessage = new WeakMap<AssistantMessage, ThinkingRunTiming[]>();
	private outputPad = 1;

	// Skill commands: command name -> skill file path
	private skillCommands = new Map<string, string>();

	// Agent subscription unsubscribe function
	private unsubscribe?: () => void;
	private signalCleanupHandlers: Array<() => void> = [];

	// Track if editor is in bash mode (text starts with !)
	private isBashMode = false;

	// lunr: mode in effect before the current plan stretch. Used by approve / `/plan off`
	// / `/plan <text>` to leave plan. Shift+Tab and `/mode` pick the destination themselves.
	private previousPermissionMode: PermissionMode | undefined;

	// lunr: mode in effect before `/goal` forced session auto. Dedicated so it cannot
	// collide with plan restore.
	private preGoalPermissionMode: PermissionMode | undefined;

	// lunr: in-memory redo stack for /undo and /redo (leaf entry ids; cleared on any
	// new user message, never persisted — undone turns reappear after restart)
	private redoStack: string[] = [];

	// lunr: one-shot guard for the session auto-name LLM call (first assistant response)
	private autoNameTriggered = false;

	// Track current bash execution component
	private bashComponent: BashExecutionComponent | undefined = undefined;

	// Track pending bash components (shown in pending area, moved to chat on submit)
	private pendingBashComponents: BashExecutionComponent[] = [];

	// Auto-compaction state
	private autoCompactionEscapeHandler?: () => void;
	private pendingCompactionRender?: { summary: string; tokensBefore: number };

	// Auto-retry state
	private retryEscapeHandler?: () => void;

	// Messages queued while compaction is running
	private compactionQueuedMessages: CompactionQueuedMessage[] = [];

	// Shutdown state
	private shutdownRequested = false;

	// Extension UI state
	private extensionSelector: ExtensionSelectorComponent | undefined = undefined;
	private extensionInput: ExtensionInputComponent | undefined = undefined;
	private extensionEditor: ExtensionEditorComponent | undefined = undefined;
	private extensionTerminalInputUnsubscribers = new Set<() => void>();

	// Extension widgets (components rendered above/below the editor)
	private extensionWidgetsAbove = new Map<string, Component & { dispose?(): void }>();
	private extensionWidgetsBelow = new Map<string, Component & { dispose?(): void }>();
	private widgetContainerAbove!: Container;
	private widgetContainerBelow!: Container;

	// Custom footer from extension (undefined = use built-in footer)
	private customFooter: (Component & { dispose?(): void }) | undefined = undefined;

	// Header container that holds the built-in or custom header
	private headerContainer: Container;

	// Built-in header (logo + keybinding hints)
	private builtInHeader: Component | undefined = undefined;

	// Custom header from extension (undefined = use built-in header)
	private customHeader: (Component & { dispose?(): void }) | undefined = undefined;

	private options: InteractiveModeOptions;
	private autoTrustOnReloadCwd: string | undefined;
	private themeController: InteractiveThemeController;
	private deferredBuiltinsAttached = false;
	private startupReadyPromise?: Promise<void>;
	private startupFeatureError?: Error;
	private deferredBuiltinAttachPromise: Promise<void> | undefined;

	// Convenience accessors
	private get session(): AgentSession {
		return this.runtimeHost.session;
	}
	private get agent() {
		return this.session.agent;
	}
	private get sessionManager() {
		return this.session.sessionManager;
	}
	private get settingsManager() {
		return this.session.settingsManager;
	}

	constructor(runtimeHost: AgentSessionRuntime, options: InteractiveModeOptions = {}) {
		this.runtimeHost = runtimeHost;
		this.options = options;
		this.autoTrustOnReloadCwd = options.autoTrustOnReloadCwd;
		this.runtimeHost.setBeforeSessionInvalidate((reason) => {
			this.resetExtensionUI();
			// lunr: reset permission mode to configured default + clear session approvals
			this.previousPermissionMode = undefined;
			this.preGoalPermissionMode = undefined;
			resetPermissions(this.settingsManager.getDefaultPermissionMode());
			// lunr: clear process registry and rollback state
			processRegistry.clearRegistry();
			// lunr: on fork (/rollback, tree navigation) the snapshots SURVIVE —
			// the caller migrates them to the forked session id (migrateRollbackSession).
			// Any other replacement wipes only the session being torn down.
			if (reason !== "fork") {
				clearRollback(this.sessionManager.getSessionId());
			}
		});
		this.runtimeHost.setRebindSession(async () => {
			await this.rebindCurrentSession({ renderBeforeBind: true });
			// lunr: re-init rollback for the new session id + re-apply auto force-enable.
			initRollback(this.settingsManager, this.sessionManager.getSessionId());
			this.syncPermissionModeEffects(this.settingsManager.getDefaultPermissionMode());
		});
		this.version = VERSION;
		this.ui = options.startupView?.ui ?? new TUI(new ProcessTerminal(), this.settingsManager.getShowHardwareCursor());
		this.ui.setClearOnShrink(this.settingsManager.getClearOnShrink());

		// lunr: register the permission-mode footer bridge (provider-side: InteractiveMode owns the state).
		registerPermissionModeBridge(() => getPermissionMode());
		registerPermissionModeControlBridge({
			enterGoalAuto: () => this.enterGoalAuto(),
			leaveGoalAuto: () => this.leaveGoalAuto(),
		});
		// lunr: reset permission mode to configured default on startup.
		resetPermissions(this.settingsManager.getDefaultPermissionMode());
		this.headerContainer = new Container();
		if (options.startupView) {
			this.headerContainer.addChild(new Spacer(1));
			this.headerContainer.addChild(options.startupView.header);
			this.customFooter = options.startupView.footer;
		}
		this.loadedResourcesContainer = new Container();
		this.chatContainer = new Container();
		this.pendingMessagesContainer = new Container();
		this.statusContainer = options.startupView?.statusContainer ?? new Container();
		this.widgetContainerAbove = new Container();
		this.widgetContainerBelow = new Container();
		this.keybindings = options.startupView?.keybindings ?? KeybindingsManager.create();
		setKeybindings(this.keybindings);
		const editorPaddingX = this.settingsManager.getEditorPaddingX();
		const autocompleteMaxVisible = this.settingsManager.getAutocompleteMaxVisible();
		this.defaultEditor =
			options.startupView?.editor ??
			new CustomEditor(this.ui, getEditorTheme(), this.keybindings, {
				paddingX: editorPaddingX,
				autocompleteMaxVisible,
			});
		this.editor = this.defaultEditor;
		options.startupView?.setCurrentEditor(() => this.editor);
		this.editorContainer = new Container();
		this.editorContainer.addChild(this.editor as Component);
		this.footerDataProvider = new FooterDataProvider(this.sessionManager.getCwd());
		this.footer = new FooterComponent(this.session, this.footerDataProvider);
		this.footer.setAutoCompactEnabled(this.session.autoCompactionEnabled);

		// Load hide thinking block setting
		this.hideThinkingBlock = this.settingsManager.getHideThinkingBlock();
		this.thinkingCollapse = this.settingsManager.getThinkingCollapse();
		this.outputPad = this.settingsManager.getOutputPad();

		// Register themes from resource loader and initialize
		setRegisteredThemes(this.session.resourceLoader.getThemes().themes);
		this.themeController = new InteractiveThemeController(
			this.ui,
			this.settingsManager,
			(message) => this.showError(message),
			() => this.updateEditorBorderColor(),
		);
	}


