	private setupKeyHandlers(): void {
		// Set up handlers on defaultEditor - they use this.editor for text access
		// so they work correctly regardless of which editor is active
		this.defaultEditor.onEscape = () => {
			const sessionId = this.session.sessionId;
			const cancellation = getSubagentCancellation(sessionId);
			const escapeAction = this.subagentEscape.press(sessionId, cancellation?.hasActiveRuns() ?? false);
			if (escapeAction) {
				this.lastEscapeTime = 0;
				if (this.session.isStreaming) this.restoreQueuedMessagesToEditor({ abort: true });
				else if (this.session.isBashRunning) this.session.abortBash();
				if (escapeAction === "children" && cancellation) {
					void cancellation
						.stop()
						.then(({ requested, failed }) => {
							if (this.session.sessionId !== sessionId) return;
							if (failed)
								this.showError(`Could not request stop for ${failed} async runs. Inspect subagent status.`);
							else if (requested)
								this.showStatus(`Stopping ${requested} async ${requested === 1 ? "run" : "runs"}`);
						})
						.catch((error: unknown) => {
							if (this.session.sessionId === sessionId)
								this.showError(error instanceof Error ? error.message : String(error));
						});
				}
				return;
			}
			if (this.session.isStreaming) {
				this.restoreQueuedMessagesToEditor({ abort: true });
			} else if (this.session.isBashRunning) {
				this.session.abortBash();
			} else if (this.isBashMode) {
				this.editor.setText("");
				this.isBashMode = false;
				this.updateEditorBorderColor();
			} else if (!this.editor.getText().trim()) {
				// Double-escape with empty editor triggers /tree, /fork, or nothing based on setting
				const action = this.settingsManager.getDoubleEscapeAction();
				if (action !== "none") {
					const now = Date.now();
					if (now - this.lastEscapeTime < 500) {
						if (action === "tree") {
							this.showTreeSelector();
						} else {
							this.showUserMessageSelector();
						}
						this.lastEscapeTime = 0;
					} else {
						this.lastEscapeTime = now;
					}
				}
			}
		};

		// Register app action handlers
		this.defaultEditor.onAction("app.clear", () => this.handleCtrlC());
		this.defaultEditor.onCtrlD = () => this.handleCtrlD();
		this.defaultEditor.onAction("app.suspend", () => this.handleCtrlZ());
		this.defaultEditor.onAction("app.thinking.cycle", () => this.cycleThinkingLevel());
		this.defaultEditor.onAction("app.mode.cycle", () => this.cyclePermissionMode());
		this.defaultEditor.onAction("app.model.cycleForward", () => this.cycleModel("forward"));
		this.defaultEditor.onAction("app.model.cycleBackward", () => this.cycleModel("backward"));

		// Global debug handler on TUI (works regardless of focus)
		this.ui.onDebug = () => this.handleDebugCommand();
		this.defaultEditor.onAction("app.model.select", () => void this.showModelSelector());
		// lunr: tool/thinking expand is per-item click; ctrl+o is not bound (tree filter still uses ctrl+o).
		this.defaultEditor.onAction("app.thinking.toggle", () => this.toggleThinkingBlockVisibility());
		this.defaultEditor.onAction("app.editor.external", () => this.openExternalEditor());
		this.defaultEditor.onAction("app.clipboard.pasteImage", () => void this.handleClipboardPaste());
		this.defaultEditor.onAction("app.message.copy", () => void this.handleCopyCommand());
		this.defaultEditor.onAction("app.message.followUp", () => this.handleFollowUp());
		this.defaultEditor.onAction("app.message.dequeue", () => this.handleDequeue());
		this.defaultEditor.onAction("app.session.new", () => this.handleClearCommand());
		this.defaultEditor.onAction("app.session.tree", () => this.showTreeSelector());
		this.defaultEditor.onAction("app.session.fork", () => this.showUserMessageSelector());
		this.defaultEditor.onAction("app.session.resume", () => this.showSessionSelector());

		this.defaultEditor.onChange = (text: string) => {
			const wasBashMode = this.isBashMode;
			this.isBashMode = text.trimStart().startsWith("!");
			if (wasBashMode !== this.isBashMode) {
				this.updateEditorBorderColor();
			}
		};

		this.ui.addInputListener((data) => {
			if (!this.ui.isPinned()) return;
			if (this.ui.hasCapturingOverlayFocus()) return;

			const viewH = this.ui.getChatViewportHeight();
			if (this.keybindings.matches(data, "app.chat.pageUp")) {
				this.ui.scrollChat(viewH);
				return { consume: true };
			}
			if (this.keybindings.matches(data, "app.chat.pageDown")) {
				this.ui.scrollChat(-viewH);
				return { consume: true };
			}

			const editorFocused = isFocusable(this.editor) && this.editor.focused;
			const singleLine = !this.editor.getText().includes("\n");
			const showingAutocomplete =
				"isShowingAutocomplete" in this.editor &&
				typeof (this.editor as { isShowingAutocomplete?: () => boolean }).isShowingAutocomplete === "function" &&
				(this.editor as { isShowingAutocomplete: () => boolean }).isShowingAutocomplete();
			if (!editorFocused || !singleLine || showingAutocomplete) return;

			if (this.keybindings.matches(data, "tui.editor.pageUp")) {
				this.ui.scrollChat(viewH);
				return { consume: true };
			}
			if (this.keybindings.matches(data, "tui.editor.pageDown")) {
				this.ui.scrollChat(-viewH);
				return { consume: true };
			}
		});
	}

	private writeClipboardImageFile(image: { bytes: Uint8Array; mimeType: string }): { path: string; mimeType: string } {
		const ext = extensionForImageMimeType(image.mimeType) ?? "png";
		const fileName = `pi-clipboard-${crypto.randomUUID()}.${ext}`;
		const filePath = path.join(os.tmpdir(), fileName);
		fs.writeFileSync(filePath, Buffer.from(image.bytes));
		return { path: filePath, mimeType: image.mimeType };
	}

	private insertImageChip(attachment: { path: string; mimeType: string }): number {
		if (this.editor.insertImageMarker) {
			return this.editor.insertImageMarker(attachment);
		}
		const existing = collectImageMarkerIds(this.editor.getText());
		const used = new Set([...existing, ...this.fallbackImageAttachments.keys()]);
		let id = 1;
		while (used.has(id)) id++;
		this.fallbackImageAttachments.set(id, { id, path: attachment.path, mimeType: attachment.mimeType });
		this.editor.insertTextAtCursor?.(formatImageMarker(id));
		return id;
	}

	private takeSubmittedImages(submittedText?: string): EditorImageAttachment[] {
		if (this.editor.takePendingImages) {
			this.fallbackImageAttachments.clear();
			return this.editor.takePendingImages();
		}
		if (this.editor.getPendingImages) {
			this.fallbackImageAttachments.clear();
			return this.editor.getPendingImages();
		}
		const pending: EditorImageAttachment[] = [];
		for (const id of collectImageMarkerIds(submittedText ?? this.editor.getText())) {
			const attachment = this.fallbackImageAttachments.get(id);
			if (attachment) pending.push(attachment);
		}
		this.fallbackImageAttachments.clear();
		return pending;
	}

	private consumeStagedSubmitImages(): ImageContent[] | undefined {
		const staged = this.stagedSubmitImages;
		this.stagedSubmitImages = undefined;
		return staged;
	}

	private async loadImageAttachments(attachments: EditorImageAttachment[]): Promise<ImageContent[] | undefined> {
		if (attachments.length === 0) return undefined;
		const images: ImageContent[] = [];
		const autoResizeImages = this.settingsManager.getImageAutoResize();
		for (const attachment of attachments) {
			try {
				const bytes = fs.readFileSync(attachment.path);
				const processed = await processImage(bytes, attachment.mimeType, { autoResizeImages });
				if (!processed.ok) {
					this.showStatus(processed.message);
					continue;
				}
				images.push({
					type: "image",
					mimeType: processed.mimeType,
					data: processed.data,
				});
			} catch (err) {
				this.showStatus(
					`Could not attach ${formatImageMarker(attachment.id)}: ${err instanceof Error ? err.message : String(err)}`,
				);
			}
		}
		return images.length > 0 ? images : undefined;
	}

	private restoreEditorDraft(text: string, images?: ImageContent[]): void {
		this.editor.setText(text);
		if (!images || images.length === 0) return;
		const ids = collectImageMarkerIds(text);
		if (ids.length === 0 || !this.editor.restoreImageMarkers) return;
		const attachments: EditorImageAttachment[] = [];
		for (let i = 0; i < Math.min(ids.length, images.length); i++) {
			const id = ids[i]!;
			const image = images[i]!;
			const saved = this.writeClipboardImageFile({
				bytes: Buffer.from(image.data, "base64"),
				mimeType: image.mimeType,
			});
			attachments.push({ id, path: saved.path, mimeType: saved.mimeType });
		}
		this.editor.restoreImageMarkers(attachments);
	}

	private restoreEditorFromTreeResult(result: { editorText?: string; editorImages?: ImageContent[] }): void {
		this.restoreEditorDraft(result.editorText ?? "", result.editorImages);
	}

	private async handleClipboardPaste(options: { textFallback?: boolean } = {}): Promise<void> {
		try {
			const image = await readClipboardImage();
			if (image) {
				const saved = this.writeClipboardImageFile(image);
				this.insertImageChip(saved);
				this.ui.requestRender();
				return;
			}

			if (options.textFallback !== false) {
				const text = await readClipboardText();
				if (text) {
					this.editor.insertTextAtCursor?.(text);
					this.ui.requestRender();
					return;
				}
			}

			this.showStatus(
				options.textFallback === false ? "Clipboard contains no image" : "Clipboard contains no image or text",
			);
		} catch (err) {
			this.showStatus(`Clipboard paste failed: ${err instanceof Error ? err.message : String(err)}`);
		}
	}

