import { type ExecFileException, execFile } from "child_process";
import { existsSync, type FSWatcher, type Stats, unwatchFile, watchFile } from "fs";
import { readFile, stat } from "fs/promises";
import { dirname, join, resolve } from "path";
import { closeWatcher, FS_WATCH_RETRY_DELAY_MS, watchWithErrorHandler } from "../utils/fs-watch.ts";

type GitPaths = {
	repoDir: string;
	commonGitDir: string;
	headPath: string;
};

/**
 * Find git metadata paths by walking up from cwd.
 * Handles both regular git repos (.git is a directory) and worktrees (.git is a file).
 */
async function findGitPaths(cwd: string): Promise<GitPaths | null> {
	let dir = cwd;
	while (true) {
		const gitPath = join(dir, ".git");
		try {
			const gitStat = await stat(gitPath);
			if (gitStat.isFile()) {
				const content = (await readFile(gitPath, "utf8")).trim();
				if (content.startsWith("gitdir: ")) {
					const gitDir = resolve(dir, content.slice(8).trim());
					const headPath = join(gitDir, "HEAD");
					await stat(headPath);
					let commonGitDir = gitDir;
					try {
						commonGitDir = resolve(gitDir, (await readFile(join(gitDir, "commondir"), "utf8")).trim());
					} catch {}
					return { repoDir: dir, commonGitDir, headPath };
				}
			} else if (gitStat.isDirectory()) {
				const headPath = join(gitPath, "HEAD");
				await stat(headPath);
				return { repoDir: dir, commonGitDir: gitPath, headPath };
			}
		} catch {}
		const parent = dirname(dir);
		if (parent === dir) return null;
		dir = parent;
	}
}

/** Sum added/removed columns from `git diff --numstat`. Binary rows (`-`) are ignored. */
export function parseGitNumstat(stdout: string): { added: number; removed: number } {
	let added = 0;
	let removed = 0;
	for (const line of stdout.split(/\r?\n/)) {
		if (!line) continue;
		const tab1 = line.indexOf("\t");
		if (tab1 <= 0) continue;
		const tab2 = line.indexOf("\t", tab1 + 1);
		if (tab2 < 0) continue;
		const addTok = line.slice(0, tab1);
		const delTok = line.slice(tab1 + 1, tab2);
		if (addTok !== "-") {
			const n = Number(addTok);
			if (Number.isFinite(n)) added += n;
		}
		if (delTok !== "-") {
			const n = Number(delTok);
			if (Number.isFinite(n)) removed += n;
		}
	}
	return { added, removed };
}

function resolveDiffstatWithGitAsync(repoDir: string): Promise<{ added: number; removed: number } | null> {
	return new Promise((resolvePromise) => {
		execFile(
			"git",
			["--no-optional-locks", "diff", "--numstat", "HEAD"],
			{
				cwd: repoDir,
				encoding: "utf8",
				timeout: 3000,
			},
			(error: ExecFileException | null, stdout: string) => {
				if (error) {
					resolvePromise(null);
					return;
				}
				resolvePromise(parseGitNumstat(stdout));
			},
		);
	});
}

/** Ask git for the current branch asynchronously. Returns null on detached HEAD or if git is unavailable. */
function resolveBranchWithGitAsync(repoDir: string): Promise<string | null> {
	return new Promise((resolvePromise) => {
		execFile(
			"git",
			["--no-optional-locks", "symbolic-ref", "--quiet", "--short", "HEAD"],
			{
				cwd: repoDir,
				encoding: "utf8",
				timeout: 3000,
			},
			(error: ExecFileException | null, stdout: string) => {
				if (error) {
					resolvePromise(null);
					return;
				}
				const branch = stdout.trim();
				resolvePromise(branch || null);
			},
		);
	});
}

function isWslEnvironment(): boolean {
	return process.platform === "linux" && !!(process.env.WSL_DISTRO_NAME || process.env.WSL_INTEROP);
}

function isWindowsMountedRepoPath(repoDir: string): boolean {
	return /^\/mnt\/[a-z](?:\/|$)/i.test(repoDir);
}

function shouldPollGitHead(repoDir: string): boolean {
	return isWslEnvironment() && isWindowsMountedRepoPath(repoDir);
}

